use super::*;

/// V-SHARP. Written out rather than generated by `param_config!` because qsm-core's working grid
/// is an enum with a payload, held here as `grid` and `grid_spacing`.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct VsharpConfig {
    /// Undo the SMV high-pass with a truncated-SVD deconvolution (Wu et al. 2012). Off (the
    /// default) returns the SMV high-pass with the largest kernel that fits at each voxel, as
    /// STI Suite's V_SHARP does.
    pub deconvolve: bool,
    /// TSVD threshold of the deconvolution; unused when `deconvolve` is off.
    pub threshold: f64,
    pub max_radius: f64,
    pub min_radius: f64,
    /// Step between successive kernel radii, in mm: the radii are `max_radius`,
    /// `max_radius - radius_step`, ... down to `min_radius`.
    pub radius_step: f64,
    /// Grid the background is estimated on: `isotropic` at [`grid_spacing`](Self::grid_spacing)
    /// (the default), `native` (the acquired grid), or `finest` (isotropic at the smallest voxel
    /// dimension).
    pub grid: VsharpGrid,
    /// Isotropic working-grid spacing in mm; used only with `grid = "isotropic"`.
    pub grid_spacing: f64,
}
impl Default for VsharpConfig {
    fn default() -> Self {
        use qsm_core::bgremove::VsharpGrid as Core;
        let p = qsm_core::bgremove::VsharpParams::default();
        let (grid, grid_spacing) = match p.grid {
            Core::Native => (VsharpGrid::Native, qsm_core::bgremove::vsharp::STI_GRID_MM),
            Core::IsotropicFinest => (VsharpGrid::Finest, qsm_core::bgremove::vsharp::STI_GRID_MM),
            Core::Isotropic { spacing_mm } => (VsharpGrid::Isotropic, spacing_mm),
        };
        Self {
            deconvolve: p.deconvolve, threshold: p.threshold, max_radius: p.max_radius, min_radius: p.min_radius,
            radius_step: p.radius_step, grid, grid_spacing,
        }
    }
}
impl VsharpConfig {
    /// The qsm-core working grid.
    pub fn core_grid(&self) -> qsm_core::bgremove::VsharpGrid {
        match self.grid {
            VsharpGrid::Native => qsm_core::bgremove::VsharpGrid::Native,
            VsharpGrid::Finest => qsm_core::bgremove::VsharpGrid::IsotropicFinest,
            VsharpGrid::Isotropic => qsm_core::bgremove::VsharpGrid::Isotropic { spacing_mm: self.grid_spacing },
        }
    }
}
// PDF's `n_pad`: zero padding around the mask's bounding box, voxels per axis (0 = the full volume).
param_config!(PdfConfig from qsm_core::bgremove::PdfParams {
    tol: f64, n_cg: usize, space: PdfSpace, n_pad: usize
});
impl PdfConfig {
    /// Why the settings cannot be used, if they cannot: a padding of 1, which `PDF.m` cannot run
    /// with on odd extents (qsm-core refuses it).
    pub fn validate(&self) -> Result<(), String> {
        if self.n_pad == 1 {
            return Err("PDF padding: must be 0 (the full volume) or at least 2 voxels (got 1)".into());
        }
        Ok(())
    }
}
// LBV (LBV.m + mexMGv6): `tol` stops the coarsest-grid relaxation on the summed absolute update,
// in radians over the echo spacing; `depth` `None` is automatic (log2 of the smallest dimension
// minus 3); `peel`: boundary layers removed beyond the first; `n1`/`n2`: relaxations per level
// before/after the coarser grid, `n3` on the finest grid at the end; `precision`: double (default)
// or the original's single. qsm-core's dispatcher fills in the scan's echo times and field
// strength; the radian conversion uses the echo spacing, as LBV.m's input does.
param_config!(LbvConfig from qsm_core::bgremove::LbvParams {
    tol: f64, depth: Option<usize>, peel: usize, n1: usize, n2: usize, n3: usize, precision: LbvPrecision
});
impl LbvConfig {
    /// qsm-core's parameters (the scan's field strength and echo times are filled in later).
    pub fn params(&self) -> qsm_core::bgremove::LbvParams {
        qsm_core::bgremove::LbvParams {
            tol: self.tol, depth: self.depth, peel: self.peel, n1: self.n1, n2: self.n2, n3: self.n3,
            precision: self.precision.into(), ..Default::default()
        }
    }
}
// iSMV: `max_iter` `None` is no cap; `radius` `None` (mm) is the variant's own: 6 × the smallest
// voxel dimension for Wen 2014, 2 × the largest for QSM.jl.
param_config!(IsmvConfig from qsm_core::bgremove::IsmvParams {
    variant: IsmvVariant, tol: f64, max_iter: Option<usize>, radius: Option<f64>
});
param_config!(SharpConfig from qsm_core::bgremove::SharpParams { threshold: f64, radius: f64 });
param_config!(ResharpConfig from qsm_core::bgremove::ResharpParams {
    radius: f64, tik_reg: f64, tol: f64, max_iter: usize
});
// `pad`: zero padding per side, voxels per axis (STI Suite's `padsize`). `rim`: which boundary-rim
// Laplacian values are set to zero (qsm-core's defaults: the whole rim for HARPERELLA, STI's 20 %
// largest for iHARPERELLA).
param_config!(HarperellaConfig from qsm_core::bgremove::HarperellaParams {
    radius: f64, max_iter: usize, tol: f64, pad: [usize; 3], rim: HarperellaRim
});
// iHARPERELLA has no SMV kernel, so no radius (QSM.rs#169).
param_config!(IharperellaConfig from qsm_core::bgremove::IharperellaParams {
    max_iter: usize, tol: f64, pad: [usize; 3], rim: HarperellaRim
});
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct BgRemovalConfig {
    pub algorithm: BfAlgorithm,
    pub vsharp: VsharpConfig,
    pub pdf: PdfConfig,
    pub lbv: LbvConfig,
    pub ismv: IsmvConfig,
    pub sharp: SharpConfig,
    pub resharp: ResharpConfig,
    pub harperella: HarperellaConfig,
    pub iharperella: IharperellaConfig,
    /// Erode the brain mask by this many voxels after field mapping, before background removal
    /// (qsm-core's `BgRemovalConfig::erode_voxels`); 0 = none. The field map is not masked again,
    /// so the method still sees the field just outside the eroded mask. Eroding in the masking
    /// stage instead would mask the field map too.
    pub erode_voxels: usize,
    /// After background removal, keep the mask's largest 26-connected component with its holes
    /// filled, and zero the local field outside it: STI Suite QSM_GUI's PolishMask (qsm-core's
    /// `BgRemovalConfig::polish_mask`).
    pub polish_mask: bool,
    /// UK Biobank's phase-reliability mask trimming (qsm-core's `BgRemovalConfig::ukb_mask_trim`,
    /// `utils::phase_reliability`): before background removal, the brain mask less the voxels whose
    /// first- or last-echo phase is unreliable (and small pieces per slice), and after it the
    /// stage's mask trimmed again more tightly (the local field left as background removal made it,
    /// as UK Biobank hands it to iLSQR). The maps come
    /// from the wrapped phase over the untrimmed brain mask, as in UK Biobank's pipeline. Set by
    /// the `uk-biobank` pipeline.
    pub ukb_mask_trim: bool,
}
impl Default for BgRemovalConfig {
    fn default() -> Self {
        Self {
            algorithm: BfAlgorithm::Vsharp,
            vsharp: VsharpConfig::default(), pdf: PdfConfig::default(),
            lbv: LbvConfig::default(), ismv: IsmvConfig::default(),
            sharp: SharpConfig::default(), resharp: ResharpConfig::default(),
            harperella: HarperellaConfig::default(), iharperella: IharperellaConfig::default(),
            erode_voxels: 0,
            polish_mask: false,
            ukb_mask_trim: false,
        }
    }
}
